import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Employee, EmployeeUpdateRequest } from '../../models/models';
import { EmployeeService } from '../../services/employee.service';
import { AuthService } from '../../services/auth.service';
import { environment } from '../../../environments/environment';

type TabType = 'overview' | 'team' | 'all' | 'report';

@Component({
  selector: 'app-manager-dashboard',
  templateUrl: './manager-dashboard.component.html'
})
export class ManagerDashboardComponent implements OnInit {
  activeTab: TabType = 'overview';
  allEmployees: Employee[] = [];
  teamEmployees: Employee[] = [];
  report: any = null;

  selectedEmployee: Employee | null = null;
  editForm!: FormGroup;

  loading = false;
  msg = '';
  msgType: 'success' | 'error' = 'success';
  searchTerm = '';
  filterDept = '';

  departments = ['Engineering','Finance','HR','Marketing','Operations','Sales','IT','Legal'];
  camundaTasklistUrl = `${environment.camundaUrl}/app/tasklist/`;

  constructor(
    private empSvc: EmployeeService,
    public auth: AuthService,
    private fb: FormBuilder
  ) {}

  ngOnInit() {
    this.editForm = this.fb.group({
      firstName:   ['', Validators.required],
      lastName:    ['', Validators.required],
      phone:       [''],
      department:  [''],
      designation: ['']
    });
    this.loadAll();
  }

  loadAll() {
    this.loading = true;
    this.empSvc.mgrGetAllEmployees().subscribe({
      next: r => { this.allEmployees = r.data ?? []; this.loading = false; },
      error: () => { this.loading = false; this.showMsg('Failed to load employees', 'error'); }
    });
    this.empSvc.mgrGetMyTeam().subscribe({
      next: r => this.teamEmployees = r.data ?? []
    });
  }

  loadReport() {
    this.empSvc.mgrGetReport().subscribe({
      next: r => this.report = r.data,
      error: () => this.showMsg('Report generation failed', 'error')
    });
  }

  get filteredAll(): Employee[] {
    return this.allEmployees.filter(e => {
      const term = this.searchTerm.toLowerCase();
      const matchSearch = !term ||
        (e.firstName + ' ' + e.lastName).toLowerCase().includes(term) ||
        e.email.toLowerCase().includes(term);
      const matchDept = !this.filterDept || e.department === this.filterDept;
      return matchSearch && matchDept;
    });
  }

  openEdit(emp: Employee) {
    this.selectedEmployee = emp;
    this.editForm.patchValue({
      firstName: emp.firstName, lastName: emp.lastName,
      phone: emp.phone ?? '', department: emp.department ?? '',
      designation: emp.designation ?? ''
    });
  }

  saveEdit() {
    if (!this.selectedEmployee || this.editForm.invalid) return;
    const req: EmployeeUpdateRequest = this.editForm.value;
    this.empSvc.mgrUpdateEmployee(this.selectedEmployee.id, req).subscribe({
      next: r => {
        const idx = this.allEmployees.findIndex(e => e.id === this.selectedEmployee!.id);
        if (idx >= 0 && r.data) this.allEmployees[idx] = r.data;
        this.selectedEmployee = null;
        this.showMsg('Employee updated!', 'success');
      },
      error: () => this.showMsg('Update failed', 'error')
    });
  }

  deleteEmployee(id: string) {
    if (!confirm('Deactivate this employee?')) return;
    this.empSvc.mgrDeleteEmployee(id).subscribe({
      next: () => {
        this.allEmployees = this.allEmployees.filter(e => e.id !== id);
        this.showMsg('Employee deactivated.', 'success');
      },
      error: () => this.showMsg('Delete failed', 'error')
    });
  }

  setTab(tab: TabType) {
    this.activeTab = tab;
    this.selectedEmployee = null;
    if (tab === 'report') this.loadReport();
  }

  showMsg(msg: string, type: 'success' | 'error') {
    this.msg = msg; this.msgType = type;
    setTimeout(() => this.msg = '', 4000);
  }

  get teamActive() { return this.teamEmployees.filter(e => e.status === 'ACTIVE').length; }
  get uniqueDepts() { return [...new Set(this.allEmployees.map(e => e.department).filter(Boolean))]; }
}
<div class="dashboard-wrapper">
  <div class="page-header">
    <div>
      <h1>📊 Manager Dashboard</h1>
      <p>View and manage your team members</p>
    </div>
    <a [href]="camundaTasklistUrl" target="_blank" class="btn-camunda">🔗 Camunda Tasklist</a>
  </div>

  <div *ngIf="msg" class="alert" [class.alert-success]="msgType==='success'" [class.alert-error]="msgType==='error'">
    {{ msg }}
  </div>

  <div class="tab-nav">
    <button [class.active]="activeTab==='overview'" (click)="setTab('overview')">📊 Overview</button>
    <button [class.active]="activeTab==='team'"     (click)="setTab('team')">👥 My Team</button>
    <button [class.active]="activeTab==='all'"      (click)="setTab('all')">🏢 All Employees</button>
    <button [class.active]="activeTab==='report'"   (click)="setTab('report')">📄 Report</button>
  </div>

  <!-- ── OVERVIEW ─────────────────────────────────────────────────────────── -->
  <div *ngIf="activeTab==='overview'">
    <div class="stats-grid">
      <div class="stat-card stat-blue">
        <div class="stat-icon">🏢</div>
        <div class="stat-value">{{ allEmployees.length }}</div>
        <div class="stat-label">All Employees</div>
      </div>
      <div class="stat-card stat-green">
        <div class="stat-icon">👥</div>
        <div class="stat-value">{{ teamEmployees.length }}</div>
        <div class="stat-label">My Team</div>
      </div>
      <div class="stat-card stat-teal">
        <div class="stat-icon">✅</div>
        <div class="stat-value">{{ teamActive }}</div>
        <div class="stat-label">Team Active</div>
      </div>
      <div class="stat-card stat-purple">
        <div class="stat-icon">🏷️</div>
        <div class="stat-value">{{ uniqueDepts.length }}</div>
        <div class="stat-label">Departments</div>
      </div>
    </div>

    <div class="card mt">
      <div class="card-header"><h3>👥 My Team Members</h3></div>
      <div class="empty-state" *ngIf="teamEmployees.length===0">No team members assigned yet.</div>
      <div class="mini-list" *ngFor="let emp of teamEmployees">
        <span class="emp-avatar">{{ emp.firstName[0] }}{{ emp.lastName[0] }}</span>
        <div class="emp-info">
          <span class="emp-name">{{ emp.firstName }} {{ emp.lastName }}</span>
          <span class="emp-sub">{{ emp.designation }} · {{ emp.department }}</span>
        </div>
        <span class="status-badge status-{{emp.status.toLowerCase()}}">{{ emp.status }}</span>
      </div>
    </div>
  </div>

  <!-- ── MY TEAM ───────────────────────────────────────────────────────────── -->
  <div *ngIf="activeTab==='team'">
    <!-- Edit panel -->
    <div class="edit-panel" *ngIf="selectedEmployee">
      <h3>✏️ Edit: {{ selectedEmployee.firstName }} {{ selectedEmployee.lastName }}</h3>
      <form [formGroup]="editForm" (ngSubmit)="saveEdit()">
        <div class="form-row">
          <div class="form-group"><label>First Name</label><input formControlName="firstName" class="form-control"/></div>
          <div class="form-group"><label>Last Name</label><input formControlName="lastName" class="form-control"/></div>
        </div>
        <div class="form-row">
          <div class="form-group"><label>Phone</label><input formControlName="phone" class="form-control"/></div>
          <div class="form-group">
            <label>Department</label>
            <select formControlName="department" class="form-control">
              <option *ngFor="let d of departments" [value]="d">{{ d }}</option>
            </select>
          </div>
        </div>
        <div class="form-group"><label>Designation</label><input formControlName="designation" class="form-control"/></div>
        <div class="btn-group">
          <button type="submit" class="btn-primary" [disabled]="editForm.invalid">Save</button>
          <button type="button" class="btn-secondary" (click)="selectedEmployee=null">Cancel</button>
        </div>
      </form>
    </div>

    <div class="table-wrap">
      <table class="data-table">
        <thead><tr><th>Name</th><th>Email</th><th>Department</th><th>Designation</th><th>Status</th><th>Actions</th></tr></thead>
        <tbody>
          <tr *ngFor="let emp of teamEmployees">
            <td>
              <div class="emp-cell">
                <span class="emp-avatar sm">{{ emp.firstName[0] }}{{ emp.lastName[0] }}</span>
                {{ emp.firstName }} {{ emp.lastName }}
              </div>
            </td>
            <td>{{ emp.email }}</td>
            <td>{{ emp.department ?? '—' }}</td>
            <td>{{ emp.designation ?? '—' }}</td>
            <td><span class="status-badge status-{{emp.status.toLowerCase()}}">{{ emp.status }}</span></td>
            <td>
              <div class="action-btns">
                <button class="btn-icon btn-edit" (click)="openEdit(emp)">✏️</button>
                <button class="btn-icon btn-del" (click)="deleteEmployee(emp.id)">🗑️</button>
              </div>
            </td>
          </tr>
          <tr *ngIf="teamEmployees.length===0"><td colspan="6" class="empty-row">No team members assigned.</td></tr>
        </tbody>
      </table>
    </div>
  </div>

  <!-- ── ALL EMPLOYEES ─────────────────────────────────────────────────────── -->
  <div *ngIf="activeTab==='all'">
    <div class="filter-bar">
      <input [(ngModel)]="searchTerm" placeholder="🔍 Search..." class="search-input"/>
      <select [(ngModel)]="filterDept" class="filter-select">
        <option value="">All Departments</option>
        <option *ngFor="let d of departments" [value]="d">{{ d }}</option>
      </select>
    </div>

    <div class="table-wrap">
      <table class="data-table">
        <thead><tr><th>Name</th><th>Email</th><th>Department</th><th>Role</th><th>Status</th><th>Actions</th></tr></thead>
        <tbody>
          <tr *ngFor="let emp of filteredAll">
            <td>
              <div class="emp-cell">
                <span class="emp-avatar sm">{{ emp.firstName[0] }}{{ emp.lastName[0] }}</span>
                {{ emp.firstName }} {{ emp.lastName }}
              </div>
            </td>
            <td>{{ emp.email }}</td>
            <td>{{ emp.department ?? '—' }}</td>
            <td><span class="role-badge role-{{emp.role.toLowerCase()}}">{{ emp.role }}</span></td>
            <td><span class="status-badge status-{{emp.status.toLowerCase()}}">{{ emp.status }}</span></td>
            <td>
              <div class="action-btns">
                <button class="btn-icon btn-edit" (click)="openEdit(emp)">✏️</button>
                <button class="btn-icon btn-del" (click)="deleteEmployee(emp.id)">🗑️</button>
              </div>
            </td>
          </tr>
          <tr *ngIf="filteredAll.length===0"><td colspan="6" class="empty-row">No employees found</td></tr>
        </tbody>
      </table>
    </div>
  </div>

  <!-- ── REPORT ─────────────────────────────────────────────────────────────── -->
  <div *ngIf="activeTab==='report'">
    <div class="card" *ngIf="report">
      <div class="card-header">
        <h3>📄 Team Report</h3>
        <span class="text-muted">Generated: {{ report.generatedAt }}</span>
      </div>
      <div class="stats-grid mt">
        <div class="stat-card stat-blue"><div class="stat-value">{{ report.totalTeam }}</div><div class="stat-label">Total Team</div></div>
        <div class="stat-card stat-green"><div class="stat-value">{{ report.active }}</div><div class="stat-label">Active</div></div>
        <div class="stat-card stat-orange"><div class="stat-value">{{ report.pending }}</div><div class="stat-label">Pending</div></div>
        <div class="stat-card stat-red"><div class="stat-value">{{ report.inactive }}</div><div class="stat-label">Inactive</div></div>
      </div>
      <div class="table-wrap mt">
        <table class="data-table">
          <thead><tr><th>Name</th><th>Email</th><th>Department</th><th>Designation</th><th>Status</th></tr></thead>
          <tbody>
            <tr *ngFor="let emp of report.employees">
              <td>{{ emp.firstName }} {{ emp.lastName }}</td>
              <td>{{ emp.email }}</td>
              <td>{{ emp.department }}</td>
              <td>{{ emp.designation }}</td>
              <td><span class="status-badge status-{{emp.status.toLowerCase()}}">{{ emp.status }}</span></td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
    <div class="loading-state" *ngIf="!report">Generating report...</div>
  </div>
</div>
